class DjangoHelpFormatter(HelpFormatter):
    """
    Customized formatter so that command-specific arguments appear in the
    --help output before arguments common to all commands.
    """

    show_last = {
        "--version",
        "--verbosity",
        "--traceback",
        "--settings",
        "--pythonpath",
        "--no-color",
        "--force-color",
        "--skip-checks",
    }

    def _reordered_actions(self, actions):
        return sorted(
            actions, key=lambda a: set(a.option_strings) & self.show_last != set()
        )

    def add_usage(self, usage, actions, *args, **kwargs):
        super().add_usage(usage, self._reordered_actions(actions), *args, **kwargs)

    def add_arguments(self, actions):
        super().add_arguments(self._reordered_actions(actions))

    def _format_text(self, text):
        """
        Format help text by preserving line breaks and indentation.
        """
        import textwrap
        text = text.strip('\n')  # Remove leading/trailing newlines
        lines = text.splitlines()
        # Find common indentation
        def get_indent(line):
            return len(line) - len(line.lstrip()) if line.strip() else None
        indents = [get_indent(line) for line in lines if get_indent(line) is not None]
        if indents:
            common_indent = min(indents)
            # Remove common indentation from each line
            lines = [line[common_indent:] if line.strip() else line for line in lines]
        # Join lines back together
        return '\n'.join(lines)

